  "deep_conversion_worth_rate",
  "deep_optimization_type",
  "end_date",
  "first_day_begin_time",
  "flow_optimization_enabled",
  "is_deleted",
  "last_modified_time",
  "marketing_scenario",
  "brand_ad_type",
  "marketing_carrier_detail",
  "marketing_carrier_type",
  "marketing_goal",
  "marketing_sub_goal",
  "marketing_target_detail",
  "marketing_target_id",
  "marketing_asset_id",
  "marketing_target_type",
  "optimization_goal",
  "product_spec",
  "scene_spec",
  "search_expand_targeting_switch",
  "search_expansion_switch",
  "site_set",
  "smart_bid_type",
  "smart_cost_cap",
  "smart_deep_roi",
  "system_status",
  "targeting",
  "targeting_id",
  "targeting_translation",
  "time_series",
  "user_action_sets",
